from collections import defaultdict


def dedupe_contacts(rows):
    GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}

    def normalize_email(raw):
        email = (raw or "").strip().lower()
        if email.count("@") == 1:
            local, domain = email.split("@")
            if domain in GMAIL_DOMAINS:
                local = local.split("+", 1)[0].replace(".", "")
                domain = "gmail.com"
            email = f"{local}@{domain}"
        return email

    def email_valid(email):
        if email.count("@") != 1:
            return False
        local, domain = email.split("@")
        return bool(local) and "." in domain and not domain.startswith(".") and not domain.endswith(".")

    def normalize_phone(raw):
        digits = "".join(ch for ch in (raw or "") if ch.isdigit())
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        return digits

    def phone_valid(phone):
        return len(phone) == 10

    # Pre-process rows; keep original index for ordering/tie-breaking.
    records = []
    for idx, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))
        ev = email_valid(email)
        pv = phone_valid(phone)
        if not ev and not pv:
            continue  # rule 4
        records.append({
            "idx": idx,
            "row": row,
            "email": email if ev else "",
            "phone": phone if pv else "",
            "last_key": (row.get("last_name", "") or "").strip().lower(),
            "updated": row.get("updated", ""),
        })

    # Union-find for transitive matching (rule 5).
    parent = list(range(len(records)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    by_email = {}
    by_phone_last = {}
    for i, rec in enumerate(records):
        if rec["email"]:
            if rec["email"] in by_email:
                union(i, by_email[rec["email"]])
            else:
                by_email[rec["email"]] = i
        if rec["phone"] and rec["last_key"]:
            key = (rec["phone"], rec["last_key"])
            if key in by_phone_last:
                union(i, by_phone_last[key])
            else:
                by_phone_last[key] = i

    groups = defaultdict(list)
    for i in range(len(records)):
        groups[find(i)].append(records[i])

    def pick(group, getter):
        """Value from most recently updated row where getter() is non-empty;
        ties on `updated` go to the earlier input row."""
        best = None
        for rec in group:
            val = getter(rec)
            if not val:
                continue
            key = (rec["updated"], -rec["idx"])
            if best is None or key > best[0]:
                best = (key, val)
        return best[1] if best else ""

    def stripped_field(name):
        return lambda rec: (rec["row"].get(name, "") or "").strip()

    output = []
    # Rule 7: order by earliest row in the group.
    for root in sorted(groups, key=lambda r: min(rec["idx"] for rec in groups[r])):
        group = groups[root]

        tags = set()
        opted_out = "N"
        for rec in group:
            for t in (rec["row"].get("tags", "") or "").split(";"):
                t = t.strip().lower()
                if t:
                    tags.add(t)
            if (rec["row"].get("opted_out", "") or "").strip().upper() == "Y":
                opted_out = "Y"

        output.append({
            "first_name": pick(group, stripped_field("first_name")),
            "last_name": pick(group, stripped_field("last_name")),
            "email": pick(group, lambda rec: rec["email"]),
            "phone": pick(group, lambda rec: rec["phone"]),
            "zip": pick(group, stripped_field("zip")),
            "tags": ";".join(sorted(tags)),
            "opted_out": opted_out,
            "updated": max(rec["updated"] for rec in group),
        })

    return output
